package com.ebuddy.config;
import com.ebuddy.security.JwtService; import org.springframework.context.annotation.Configuration; import org.springframework.messaging.*; import org.springframework.messaging.simp.config.ChannelRegistration; import org.springframework.messaging.simp.stomp.*; import org.springframework.messaging.support.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import java.util.*;
@Configuration public class StompAuthInterceptor implements org.springframework.web.socket.config.annotation.WebSocketMessageBrokerConfigurer { private final JwtService jwt; public StompAuthInterceptor(JwtService j){jwt=j;} public void configureClientInboundChannel(ChannelRegistration r){r.interceptors(new ChannelInterceptor(){public Message<?> preSend(Message<?> m,MessageChannel c){StompHeaderAccessor a=StompHeaderAccessor.wrap(m);if(StompCommand.CONNECT.equals(a.getCommand())){String h=a.getFirstNativeHeader("authorization");if(h==null||!h.startsWith("Bearer "))throw new IllegalArgumentException("AUTH_REQUIRED");a.setUser(new UsernamePasswordAuthenticationToken(jwt.subject(h.substring(7)),null,List.of()));}return MessageBuilder.createMessage(m.getPayload(),a.getMessageHeaders());}});}}
